"use client"

import { Auth01 } from "@/registry/blocks/auth-01/auth-01"

/**
 * 登录页入口：把下面几个回调换成你自己的认证实现。
 * 回调返回 Promise；失败时 throw new Error("中文原因")，组件会显示在表单上方。
 * 登录成功后的跳转请在 onSignIn / onSocialSignIn 里自行处理，例如 router.push("/")。
 */
export default function LoginPage() {
  return (
    <Auth01
      brand={{ name: "Acme" }}
      onSignIn={async (values) => {
        // TODO: 调用你的认证服务，例如 authClient.signIn.email(...)
        console.info("sign in", values)
        await new Promise((resolve) => setTimeout(resolve, 600))
      }}
      onSignUp={async (values) => {
        console.info("sign up", values)
        await new Promise((resolve) => setTimeout(resolve, 600))
      }}
      onForgotPassword={async (email) => {
        console.info("forgot password", email)
        await new Promise((resolve) => setTimeout(resolve, 600))
      }}
      onSendCode={async (phone) => {
        console.info("send code", phone)
        await new Promise((resolve) => setTimeout(resolve, 600))
      }}
      onSocialSignIn={async (provider) => {
        console.info("social sign in", provider)
        await new Promise((resolve) => setTimeout(resolve, 600))
      }}
    />
  )
}

"use client"

import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { useState } from "react"

import { cn } from "@/lib/utils"

import { defaultBrand, type BrandConfig, type BrandFeature } from "./brand"
import { BrandPanel, MobileBrand } from "./brand-panel"
import type { Auth01Labels } from "./config"
import { ForgotPasswordForm } from "./forgot-password-form"
import { SignInForm, type SignInValues } from "./sign-in-form"
import { SignUpForm, type SignUpValues } from "./sign-up-form"
import type { SocialProvider } from "./social-buttons"

type AuthView = "sign-in" | "sign-up" | "forgot-password"

const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))
// 未传回调时的示例实现：只在控制台打印，并模拟 0.8 秒的网络请求
const demo =
  <Args extends unknown[]>(name: string) =>
  async (...args: Args) => {
    console.info(`[auth-01] ${name}`, ...args)
    await wait(800)
  }

/**
 * 分屏式登录 / 注册页：左侧品牌面板 + 右侧表单，窄屏只显示表单。
 * 回调返回 Promise；组件管理 loading，回调 throw 的 Error.message 会显示为表单错误。
 */
function Auth01({
  brand,
  defaultView = "sign-in",
  socialProviders = ["github", "google"],
  allowSignUp = true,
  termsHref = "#",
  privacyHref = "#",
  onSignIn = demo<[SignInValues]>("onSignIn"),
  onSignUp = demo<[SignUpValues]>("onSignUp"),
  onForgotPassword = demo<[string]>("onForgotPassword"),
  onSendCode = demo<[string]>("onSendCode"),
  onSocialSignIn = demo<[SocialProvider]>("onSocialSignIn"),
  labels,
  className,
}: {
  /** 品牌信息，逐项覆盖默认的示例品牌 */
  brand?: Partial<BrandConfig>
  defaultView?: AuthView
  /** 启用的第三方登录，传空数组隐藏该区域 */
  socialProviders?: readonly SocialProvider[]
  /** 设为 false 隐藏「注册」入口（仅邀请制的产品） */
  allowSignUp?: boolean
  termsHref?: string
  privacyHref?: string
  onSignIn?: (values: SignInValues) => Promise<void>
  onSignUp?: (values: SignUpValues) => Promise<void>
  onForgotPassword?: (email: string) => Promise<void>
  onSendCode?: (phone: string) => Promise<void>
  onSocialSignIn?: (provider: SocialProvider) => Promise<void>
  /** 覆盖默认文案，见 config.ts 的 DEFAULT_LABELS */
  labels?: Partial<Auth01Labels>
  className?: string
}) {
  const [view, setView] = useState<AuthView>(defaultView)
  const reducedMotion = useReducedMotion()
  const resolved: BrandConfig = { ...defaultBrand, ...brand }
  return (
    <div data-slot="auth-01" className={cn("relative flex min-h-svh", className)}>
      <BrandPanel brand={resolved} labels={labels} />
      <main className="relative flex flex-1 items-center justify-center bg-background p-6 pb-16 sm:p-12 sm:pb-16">
        <div className="w-full max-w-md">
          <MobileBrand brand={resolved} />
          <AnimatePresence mode="wait" initial={false}>
            <motion.div
              key={view}
              initial={{ opacity: 0, y: reducedMotion ? 0 : 8 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: reducedMotion ? 0 : -8 }}
              transition={{ duration: 0.18 }}
            >
              {view === "sign-in" && (
                <SignInForm
                  socialProviders={socialProviders}
                  allowSignUp={allowSignUp}
                  onSignIn={onSignIn}
                  onSendCode={onSendCode}
                  onSocialSignIn={onSocialSignIn}
                  onForgotPassword={() => setView("forgot-password")}
                  onSwitchToSignUp={() => setView("sign-up")}
                  labels={labels}
                />
              )}
              {view === "sign-up" && (
                <SignUpForm
                  termsHref={termsHref}
                  privacyHref={privacyHref}
                  onSignUp={onSignUp}
                  onSwitchToSignIn={() => setView("sign-in")}
                  labels={labels}
                />
              )}
              {view === "forgot-password" && (
                <ForgotPasswordForm
                  onForgotPassword={onForgotPassword}
                  onSwitchToSignIn={() => setView("sign-in")}
                  labels={labels}
                />
              )}
            </motion.div>
          </AnimatePresence>
        </div>
        <p className="absolute right-6 bottom-4 text-xs text-muted-foreground">
          {resolved.copyright}
        </p>
      </main>
    </div>
  )
}

export { Auth01 }
export type {
  Auth01Labels,
  AuthView,
  BrandConfig,
  BrandFeature,
  SignInValues,
  SignUpValues,
  SocialProvider,
}

import { Gauge, Hexagon, ShieldCheck, Zap } from "lucide-react"
import type { ReactNode } from "react"

type BrandFeature = {
  icon: ReactNode
  title: string
  description: string
}

type BrandConfig = {
  /** 产品名，显示在 Logo 旁 */
  name: string
  /** Logo 节点：建议用 currentColor 的 SVG，这样在品牌面板（反色）和表单上方（正常色）都能看清 */
  logo: ReactNode
  /** 品牌面板的大标题 */
  title: string
  description: string
  /** 品牌面板上的特性列表，建议 2–3 条 */
  features: BrandFeature[]
  /** 右下角的版权文字 */
  copyright: string
}

/** 示例品牌：换成自己的产品信息，或通过 Auth01 的 brand 属性逐项覆盖。 */
const defaultBrand: BrandConfig = {
  name: "Acme",
  logo: <Hexagon strokeWidth={1.5} />,
  title: "把想法变成可用的产品",
  description: "一个账号，打开全部工具。登录后继续上次的工作，随时随地保持同步。",
  features: [
    {
      icon: <Zap />,
      title: "快速上手",
      description: "几分钟完成配置，立刻开始使用",
    },
    {
      icon: <Gauge />,
      title: "稳定可靠",
      description: "全天候运行，关键数据实时同步",
    },
    {
      icon: <ShieldCheck />,
      title: "安全优先",
      description: "加密传输，权限精细可控",
    },
  ],
  copyright: "© 2026 Acme. 保留所有权利。",
}

export { defaultBrand }
export type { BrandConfig, BrandFeature }

import { cn } from "@/lib/utils"
import { GlyphField } from "@/registry/ui/glyph-field/glyph-field"
import { Ripple } from "@/registry/ui/ripple/ripple"
import { TextReveal } from "@/registry/ui/text-animate/text-animate"

import type { BrandConfig } from "./brand"
import { formatLabel, resolveLabels, type Auth01Labels } from "./config"

function Logo({
  logo,
  className,
}: {
  logo: BrandConfig["logo"]
  className: string
}) {
  // 外层限定尺寸，内部的 svg / img 自动缩放到框内
  return (
    <span
      data-slot="auth-01-brand-logo"
      aria-hidden="true"
      className={cn(
        "flex shrink-0 items-center justify-center [&>*]:max-h-full [&>*]:max-w-full [&>svg]:size-full",
        className,
      )}
    >
      {logo}
    </span>
  )
}

/**
 * 大屏左半边的品牌面板：主色渐变 + 模糊光斑 + 向外扩散的波纹 + 四周的字符矩阵。
 * 亮色下是主色底配 primary-foreground 文字；暗色下 primary 会变成浅色，整块面板会变亮，
 * 所以暗色改为 card 深底，只用 primary 的低透明度渐变染上主题色，文字回到 foreground。
 * 光斑、波纹、字符矩阵、图标底共用 --panel-glow，随亮暗一起切换。
 */
function BrandPanel({
  brand,
  labels,
}: {
  brand: BrandConfig
  labels?: Partial<Auth01Labels>
}) {
  const text = resolveLabels(labels)
  return (
    <aside
      data-slot="auth-01-brand-panel"
      aria-label={formatLabel(text.brandPanelLabel, { name: brand.name })}
      className="relative hidden overflow-hidden bg-linear-to-br from-primary/90 via-primary to-primary/80 text-primary-foreground [--panel-glow:var(--primary-foreground)] lg:flex lg:w-1/2 dark:bg-card dark:from-primary/16 dark:via-primary/7 dark:to-primary/3 dark:text-foreground dark:[--panel-glow:var(--primary)]"
    >
      <div aria-hidden="true" className="absolute inset-0">
        <div className="absolute top-20 left-10 size-72 rounded-full bg-(--panel-glow)/10 blur-3xl" />
        <div className="absolute right-10 bottom-20 size-96 rounded-full bg-(--panel-glow)/5 blur-3xl" />
        {/* 字符矩阵只铺在四周，中间留白给文字；GlyphField 自带底色，这里改成透明 */}
        <GlyphField
          fade="center"
          glyphs="01"
          tone="var(--panel-glow)"
          density={0.4}
          fontSize={13}
          speed={0.02}
          className="absolute inset-0 min-h-0 bg-transparent opacity-25"
        />
        <Ripple
          size={720}
          rings={4}
          ringGap={140}
          baseSize={200}
          duration={8}
          background="none"
          tone="var(--panel-glow)"
          className="absolute inset-0 h-full"
        />
      </div>
      <div className="relative z-10 flex flex-col justify-center px-12 xl:px-20">
        <div className="mb-8 flex items-center gap-3">
          <Logo logo={brand.logo} className="size-14" />
          <span className="text-2xl font-bold" translate="no">
            {brand.name}
          </span>
        </div>
        <p className="mb-6 text-2xl leading-tight font-bold text-balance xl:text-3xl">
          <TextReveal by="word" trigger="mount" stagger={70}>
            {brand.title}
          </TextReveal>
        </p>
        <p className="mb-10 max-w-md text-lg leading-8 text-current/80">
          {brand.description}
        </p>
        <ul className="flex flex-col gap-4">
          {brand.features.map((feature) => (
            <li key={feature.title} className="flex items-center gap-4">
              <span
                aria-hidden="true"
                className="rounded-lg bg-(--panel-glow)/20 p-2 [&_svg]:size-5"
              >
                {feature.icon}
              </span>
              <div>
                <div className="font-medium">{feature.title}</div>
                <div className="text-sm text-current/70">
                  {feature.description}
                </div>
              </div>
            </li>
          ))}
        </ul>
      </div>
    </aside>
  )
}

/** 窄屏下表单上方的 Logo + 名称（品牌面板此时被隐藏）。 */
function MobileBrand({ brand }: { brand: BrandConfig }) {
  return (
    <div
      data-slot="auth-01-mobile-brand"
      className="mb-8 flex items-center justify-center gap-2 lg:hidden"
    >
      <Logo logo={brand.logo} className="size-10" />
      <span className="text-xl font-bold" translate="no">
        {brand.name}
      </span>
    </div>
  )
}

export { BrandPanel, MobileBrand }

"use client"

import { KeyRound, Lock, Smartphone, User } from "lucide-react"
import { useEffect, useMemo, useState } from "react"

import { Button } from "@/components/ui/button"
import { SegmentedControl } from "@/registry/ui/segmented-control/segmented-control"
import { ToggleSwitch } from "@/registry/ui/toggle-switch/toggle-switch"

import { formatLabel, resolveLabels, type Auth01Labels } from "./config"
import {
  FormError,
  LinkButton,
  PasswordField,
  SubmitButton,
  TextField,
  ViewHeading,
} from "./form-parts"
import { createCodeSignInSchema, createSignInSchema } from "./schemas"
import { SocialButtons, type SocialProvider } from "./social-buttons"
import { useAsyncAction, useAuthForm } from "./use-auth-form"

type SignInValues =
  | { method: "password"; account: string; password: string; remember: boolean }
  | { method: "code"; phone: string; code: string }

type SignInMethod = SignInValues["method"]

const CODE_COOLDOWN = 60

function PasswordSignIn({
  onSignIn,
  onForgotPassword,
  labels,
}: {
  onSignIn: (values: SignInValues) => Promise<void>
  onForgotPassword: () => void
  labels?: Partial<Auth01Labels>
}) {
  // labels 引用不变时 text 与 schema 都不重建，避免每次输入都重新编译 zod schema
  const text = useMemo(() => resolveLabels(labels), [labels])
  const schema = useMemo(() => createSignInSchema(text), [text])
  const form = useAuthForm(
    schema,
    { account: "", password: "", remember: false },
    { fallbackError: text.requestFailed },
  )
  return (
    <form
      data-slot="auth-01-sign-in-password"
      noValidate
      onSubmit={form.handleSubmit((values) =>
        onSignIn({ method: "password", ...values }),
      )}
      className="flex flex-col gap-5"
    >
      <FormError message={form.formError} />
      <TextField
        id="sign-in-account"
        label={text.accountLabel}
        icon={User}
        autoComplete="username"
        placeholder={text.accountPlaceholder}
        value={form.values.account}
        error={form.errors.account}
        onChange={(event) => form.setValue("account", event.target.value)}
        onBlur={() => form.blur("account")}
      />
      <PasswordField
        id="sign-in-password"
        label={text.passwordLabel}
        icon={Lock}
        autoComplete="current-password"
        placeholder={text.passwordPlaceholder}
        value={form.values.password}
        error={form.errors.password}
        onChange={(event) => form.setValue("password", event.target.value)}
        onBlur={() => form.blur("password")}
        labels={labels}
        labelAction={
          <LinkButton className="text-xs" onClick={onForgotPassword}>
            {text.forgotPassword}
          </LinkButton>
        }
      />
      {/* 记住登录状态是即时生效的开关，不是需要同意的声明，所以用开关而不是复选框 */}
      <ToggleSwitch
        label={text.remember}
        tone="primary"
        checked={form.values.remember}
        onCheckedChange={(checked) => form.setValue("remember", checked)}
      />
      <SubmitButton pending={form.pending} pendingText={text.signInPending}>
        {text.signInSubmit}
      </SubmitButton>
    </form>
  )
}

function CodeSignIn({
  onSignIn,
  onSendCode,
  labels,
}: {
  onSignIn: (values: SignInValues) => Promise<void>
  onSendCode: (phone: string) => Promise<void>
  labels?: Partial<Auth01Labels>
}) {
  const text = useMemo(() => resolveLabels(labels), [labels])
  const schema = useMemo(() => createCodeSignInSchema(text), [text])
  const form = useAuthForm(
    schema,
    { phone: "", code: "" },
    { fallbackError: text.requestFailed },
  )
  const sender = useAsyncAction(text.requestFailed)
  const [seconds, setSeconds] = useState(0)
  useEffect(() => {
    if (seconds <= 0) return
    const timer = window.setTimeout(
      () => setSeconds((value) => value - 1),
      1000,
    )
    return () => window.clearTimeout(timer)
  }, [seconds])

  const sendCode = async () => {
    if (!form.validateField("phone")) return
    const sent = await sender.run(() => onSendCode(form.values.phone.trim()))
    if (sent) setSeconds(CODE_COOLDOWN)
  }
  return (
    <form
      data-slot="auth-01-sign-in-code"
      noValidate
      onSubmit={form.handleSubmit((values) =>
        onSignIn({ method: "code", ...values }),
      )}
      className="flex flex-col gap-5"
    >
      <FormError message={form.formError ?? sender.error} />
      <TextField
        id="sign-in-phone"
        label={text.phoneLabel}
        icon={Smartphone}
        type="tel"
        inputMode="numeric"
        autoComplete="tel"
        placeholder={text.phonePlaceholder}
        value={form.values.phone}
        error={form.errors.phone}
        onChange={(event) => form.setValue("phone", event.target.value)}
        onBlur={() => form.blur("phone")}
      />
      <TextField
        id="sign-in-code"
        label={text.codeLabel}
        icon={KeyRound}
        inputMode="numeric"
        maxLength={6}
        autoComplete="one-time-code"
        placeholder={text.codePlaceholder}
        value={form.values.code}
        error={form.errors.code}
        onChange={(event) => form.setValue("code", event.target.value)}
        onBlur={() => form.blur("code")}
        adjacent={
          <Button
            type="button"
            variant="outline"
            size="lg"
            className="w-28 shrink-0 tabular-nums"
            disabled={sender.pending || seconds > 0}
            onClick={sendCode}
          >
            {sender.pending
              ? text.sendCodePending
              : seconds > 0
                ? formatLabel(text.resendCode, { seconds })
                : text.sendCode}
          </Button>
        }
      />
      <SubmitButton pending={form.pending} pendingText={text.signInPending}>
        {text.signInSubmit}
      </SubmitButton>
    </form>
  )
}

function SignInForm({
  socialProviders,
  allowSignUp,
  onSignIn,
  onSendCode,
  onSocialSignIn,
  onForgotPassword,
  onSwitchToSignUp,
  labels,
}: {
  socialProviders: readonly SocialProvider[]
  allowSignUp: boolean
  onSignIn: (values: SignInValues) => Promise<void>
  onSendCode: (phone: string) => Promise<void>
  onSocialSignIn: (provider: SocialProvider) => Promise<void>
  onForgotPassword: () => void
  onSwitchToSignUp: () => void
  labels?: Partial<Auth01Labels>
}) {
  const text = resolveLabels(labels)
  const [method, setMethod] = useState<SignInMethod>("password")
  const methodOptions = [
    { value: "password", label: text.signInPasswordTab },
    { value: "code", label: text.signInCodeTab },
  ] as const
  const social = useAsyncAction(text.requestFailed)
  return (
    <div data-slot="auth-01-sign-in" className="flex flex-col gap-5">
      <ViewHeading
        title={text.signInTitle}
        description={text.signInDescription}
      />
      <div className="flex flex-col gap-3">
        <SegmentedControl
          aria-label={text.signInMethodLabel}
          size="lg"
          options={methodOptions}
          value={method}
          onValueChange={(value) => setMethod(value as SignInMethod)}
        />
        {method === "password" ? (
          <PasswordSignIn
            onSignIn={onSignIn}
            onForgotPassword={onForgotPassword}
            labels={labels}
          />
        ) : (
          <CodeSignIn
            onSignIn={onSignIn}
            onSendCode={onSendCode}
            labels={labels}
          />
        )}
      </div>
      {socialProviders.length > 0 && (
        <>
          <div
            role="separator"
            className="flex items-center gap-3 text-xs text-muted-foreground before:h-px before:flex-1 before:bg-border after:h-px after:flex-1 after:bg-border"
          >
            {text.socialDivider}
          </div>
          <FormError message={social.error} />
          <SocialButtons
            providers={socialProviders}
            pending={social.pending}
            onSelect={(provider) => social.run(() => onSocialSignIn(provider))}
          />
        </>
      )}
      {allowSignUp && (
        <p className="text-center text-sm text-muted-foreground">
          {text.noAccount}{" "}
          <LinkButton onClick={onSwitchToSignUp}>{text.signUpLink}</LinkButton>
        </p>
      )}
    </div>
  )
}

export { SignInForm }
export type { SignInValues }

"use client"

import { Lock, Mail, User } from "lucide-react"
import { useMemo } from "react"

import { Checkbox } from "@/components/ui/checkbox"
import { Label } from "@/components/ui/label"

import { resolveLabels, type Auth01Labels } from "./config"
import {
  FormError,
  LinkButton,
  PasswordField,
  SubmitButton,
  TextField,
  ViewHeading,
} from "./form-parts"
import { PasswordStrength } from "./password-strength"
import { createSignUpSchema } from "./schemas"
import { useAuthForm } from "./use-auth-form"

type SignUpValues = { name: string; email: string; password: string }

function SignUpForm({
  termsHref,
  privacyHref,
  onSignUp,
  onSwitchToSignIn,
  labels,
}: {
  termsHref: string
  privacyHref: string
  onSignUp: (values: SignUpValues) => Promise<void>
  onSwitchToSignIn: () => void
  labels?: Partial<Auth01Labels>
}) {
  // labels 引用不变时 text 与 schema 都不重建，避免每次输入都重新编译 zod schema
  const text = useMemo(() => resolveLabels(labels), [labels])
  const schema = useMemo(() => createSignUpSchema(text), [text])
  const form = useAuthForm(
    schema,
    {
      name: "",
      email: "",
      password: "",
      confirm: "",
      terms: false,
    },
    { fallbackError: text.requestFailed },
  )
  return (
    <div data-slot="auth-01-sign-up" className="flex flex-col gap-5">
      <ViewHeading title={text.signUpTitle} description={text.signUpDescription} />
      <form
        noValidate
        onSubmit={form.handleSubmit(({ name, email, password }) =>
          onSignUp({ name: name.trim(), email: email.trim(), password }),
        )}
        className="flex flex-col gap-4"
      >
        <FormError message={form.formError} />
        <TextField
          id="sign-up-name"
          label={text.nameLabel}
          icon={User}
          autoComplete="name"
          placeholder={text.namePlaceholder}
          value={form.values.name}
          error={form.errors.name}
          onChange={(event) => form.setValue("name", event.target.value)}
          onBlur={() => form.blur("name")}
        />
        <TextField
          id="sign-up-email"
          label={text.emailLabel}
          icon={Mail}
          type="email"
          autoComplete="email"
          placeholder={text.emailPlaceholder}
          value={form.values.email}
          error={form.errors.email}
          onChange={(event) => form.setValue("email", event.target.value)}
          onBlur={() => form.blur("email")}
        />
        <div className="flex flex-col gap-2">
          <PasswordField
            id="sign-up-password"
            label={text.passwordLabel}
            icon={Lock}
            autoComplete="new-password"
            placeholder={text.newPasswordPlaceholder}
            value={form.values.password}
            error={form.errors.password}
            onChange={(event) => form.setValue("password", event.target.value)}
            onBlur={() => form.blur("password")}
            labels={labels}
          />
          <PasswordStrength password={form.values.password} labels={labels} />
        </div>
        <PasswordField
          id="sign-up-confirm"
          label={text.confirmPasswordLabel}
          icon={Lock}
          autoComplete="new-password"
          placeholder={text.confirmPasswordPlaceholder}
          value={form.values.confirm}
          error={form.errors.confirm}
